with exploded as (select id, effective_from, currency, explode(tier_limits) as element from price_tiers) select date_trunc('week', effective_from) as week_start, size(collect_set(currency)) as num_currencies, count(*) filter (where currency = 'USD') as usd_rows, approx_percentile(element, array(0.25, 0.5, 0.75)) as element_quartiles from exploded group by cube (date_trunc('week', effective_from));
